import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Img,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FacebookNotificationProps = Record<string, any>;

const FacebookNotification: React.FC<FacebookNotificationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  title = "New Message",
  message = "You have a new friend request",
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Lato"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation for box and icon (grow in)
  const boxGrowProgress = spring({
    frame,
    fps,
    config: {
      damping: 10,
      stiffness: 100,
      mass: 0.5,
    },
    durationInFrames: 30,
  });

  // Animation for text elements (slide in from right)
  const textSlideProgress = spring({
    frame: frame - 15, // Delay text animation by 15 frames
    fps,
    config: {
      damping: 12,
      stiffness: 120,
      mass: 0.3,
    },
    durationInFrames: 25,
  });

  // Transform values
  const boxScale = interpolate(boxGrowProgress, [0, 1], [0, 1]);
  const iconScale = interpolate(boxGrowProgress, [0, 1], [0, 1]);
  const textTranslateX = interpolate(textSlideProgress, [0, 1], [100, 0]);
  const textOpacity = interpolate(textSlideProgress, [0, 1], [0, 1]);

  // Responsive Scaling Logic
  // The original design uses a fixed 960px width.
  // We calculate a scale factor to make it responsive on different screen sizes.
  // Base design width is around 1200px (including margins for the 960px card).
  const designBaseWidth = 1200;
  const responsiveScale = width / designBaseWidth;
  // Cap the scale at 1.5 to match the original "transform: scale(1.5)" intent on large screens,
  // but prevent it from being too small on mobile.
  const finalScale = Math.min(Math.max(responsiveScale, 0.5), 1.5);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Lato, sans-serif",
      }}
    >
      <div
        style={{
          transform: `scale(${finalScale})`,
          width: 960,
          height: 192,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {/* Horizontal rectangle box */}
        <div
          style={{
            width: 960,
            height: 192,
            backgroundColor: "#E6E6E6",
            opacity: 0.9,
            borderRadius: 56,
            position: "relative",
            display: "flex",
            alignItems: "center",
            transform: `scale(${boxScale})`,
            boxShadow: "0 10px 30px rgba(0,0,0,0.15)", // Added subtle shadow for depth
            transition: "none",
          }}
        >
          {/* Facebook logo */}
          <Img
            src="https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/logos/facebook_app.webp"
            style={{
              width: 120,
              height: 120,
              marginLeft: 36,
              borderRadius: 12,
              transform: `scale(${iconScale})`,
              transition: "none",
            }}
            alt="Facebook logo"
          />

          {/* Title text */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: 192, // 36px (left margin) + 120px (icon width) + 36px (gap)
              transform: `translateX(${textTranslateX}px) translateY(-100%)`,
              fontSize: 42,
              fontWeight: 700,
              lineHeight: 1.2,
              color: "#000000",
              opacity: textOpacity,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              maxWidth: 600,
              transition: "none",
            }}
          >
            {title}
          </div>

          {/* Message text */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: 192,
              transform: `translateX(${textTranslateX}px) translateY(0%)`,
              fontSize: 42,
              fontWeight: 400,
              lineHeight: 1.2,
              color: "#000000",
              opacity: textOpacity,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              maxWidth: 600,
              transition: "none",
            }}
          >
            {message}
          </div>

          {/* "now" timestamp */}
          <div
            style={{
              position: "absolute",
              top: 40,
              right: 48,
              fontSize: 36,
              fontWeight: 400,
              lineHeight: 1.2,
              color: "#000000",
              opacity: 0.4 * textOpacity,
              transform: `translateX(${textTranslateX}px)`,
              transition: "none",
            }}
          >
            now
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FacebookNotification;